#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <brotli/decode.h>
#include <brotli/encode.h>

int main() {
    // Compress 1MB of 'A'
    size_t input_size = 1000000;
    unsigned char* input = malloc(input_size);
    memset(input, 'A', input_size);
    size_t max_encoded = input_size + input_size / 3 + 128;
    unsigned char* encoded = malloc(max_encoded);
    size_t encoded_size = max_encoded;
    BrotliEncoderCompress(11, 22, BROTLI_MODE_GENERIC, input_size, input,
                          &encoded_size, encoded);
    printf("compressed size: %zu\n", encoded_size);

    BrotliDecoderState* state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
    size_t available_in = encoded_size;
    const uint8_t* next_in = encoded;
    size_t total_out = 0;
    unsigned char* arr = malloc(131072);

    // Decompress 131072 bytes
    size_t available_out = 131072;
    uint8_t* next_out = arr;
    BrotliDecoderResult result = BrotliDecoderDecompressStream(state, &available_in, &next_in, &available_out, &next_out, &total_out);
    printf("after fill: total_out=%zu avail_out=%zu result=%d\n", total_out, available_out, result);

    // Now call with avail_out=0
    available_out = 0;
    next_out = arr + total_out;
    result = BrotliDecoderDecompressStream(state, &available_in, &next_in, &available_out, &next_out, &total_out);
    printf("after avail=0: total_out=%zu avail_out=%zu result=%d\n", total_out, available_out, result);

    BrotliDecoderDestroyInstance(state);
    free(arr);
    free(input);
    free(encoded);
    return 0;
}
